export function getContentPage(pages: ContentPage[], slug: string) {
  const page = pages.find((item) => item.slug === slug);
  if (!page) return undefined;
  return {
    ...page,
    title: fixSpanishEncoding(page.title),
    html: fixSpanishEncoding(page.html),
  };
}

export function getForumPage(slug: string) {
  return apologeticsForums.find((forum) => forum.slug === slug);
}
